import math


def rank_artifact_submissions(submissions, expected_files):
    if not isinstance(submissions, list) or not isinstance(expected_files, list):
        raise TypeError("arguments must be lists")
    if any(not isinstance(name, str) for name in expected_files):
        raise TypeError("expected file names must be strings")
    if any(not name for name in expected_files):
        raise ValueError("expected file names must not be empty")
    if len(set(expected_files)) != len(expected_files):
        raise ValueError("expected file names must be unique")
    expected = set(expected_files)

    ranked = []
    for index, submission in enumerate(submissions):
        if not isinstance(submission, dict):
            raise TypeError("submissions must contain dictionaries")
        if set(submission) != {"team", "members", "files", "score"}:
            raise ValueError("submission keys are invalid")
        team = submission["team"]
        members = submission["members"]
        files = submission["files"]
        score = submission["score"]
        if not isinstance(team, str):
            raise TypeError("team must be a string")
        team = team.strip()
        if not team:
            raise ValueError("team must not be blank")
        if not isinstance(members, list) or not isinstance(files, list):
            raise TypeError("members and files must be lists")
        if not members:
            raise ValueError("members must not be empty")
        if any(not isinstance(member, str) for member in members):
            raise TypeError("members must be strings")
        normalized_members = [member.strip() for member in members]
        if any(not member for member in normalized_members):
            raise ValueError("members must not be blank")
        if len(set(normalized_members)) != len(normalized_members):
            raise ValueError("members must be unique")
        if any(not isinstance(name, str) for name in files):
            raise TypeError("file names must be strings")
        if len(set(files)) != len(files):
            raise ValueError("file names must be unique")
        if set(files) != expected:
            raise ValueError("submitted files do not match expected files")
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError("score must be numeric")
        if not math.isfinite(score):
            raise ValueError("score must be finite")
        ranked.append((score, team.casefold(), index, {"team": team, "members": normalized_members, "score": score}))

    ranked.sort(key=lambda item: (-item[0], item[1], -item[2]))
    return [item[3] for item in ranked]

